def install_watch_rt
  reset_watch_rt unless @watch_rt
  @watch_rt[:capability] = @capability
  @watch_rt[:enable_watch_timer] = @enable_watch_timer
  @watch_rt[:enable_stat_watcher] = @enable_stat_watcher
  @watch_rt[:rotate_wait] = @rotate_wait
  @watch_rt[:read_from_head] = @read_from_head
  @watch_rt[:read_lines_limit] = @read_lines_limit
  @watch_rt[:open_on_every_update] = @open_on_every_update
  @watch_rt[:encoding] = @encoding
  @watch_rt[:from_encoding] = @from_encoding
  @watch_rt_gen += 1
  @watch_rt
end

def probe_watch_rt_capability
  cap = @watch_rt && @watch_rt[:capability]
  if cap
    readable = cap.have_capability?(:effective, :dac_read_search) ||
      cap.have_capability?(:effective, :dac_override)
    @watch_rt_caps[:effective_read] = readable
    readable
  else
    @watch_rt_caps[:effective_read] = false
    false
  end
end

def watch_rt_capability_cache
  cluster_state = @watch_rt
  if @watch_rt_caps.key?(:effective_read)
    @watch_rt_caps[:effective_read]
  else
    probe_watch_rt_capability
  end
end

def note_event_loop_attach(watcher)
  cluster_state = @watch_rt
  return watcher unless watcher
  unless @watch_rt_attached.include?(watcher)
    @watch_rt_attached << watcher
  end
  @watch_rt_gen += 1
  watcher
end

def note_event_loop_detach(watcher)
  cluster_state = @watch_rt
  if watcher
    @watch_rt_attached.delete(watcher)
    @watch_rt_gen += 1
  end
  watcher
end

